// ===================================================================
// REPLACE THIS NODE with real sources.
//
// Drag in a Google Calendar node (Get Many events) and a Gmail node
// (Get Many messages, filter: is:unread), wire both between the webhook
// and the node below, then read their output here instead of the
// placeholder arrays.
//
// It is left as a Code node on purpose: shipping a Gmail node config
// that expects credentials you have not created would fail on import
// and tell you nothing useful.
// ===================================================================

const args = $input.first().json.body ?? {};
const day = args.day || 'today';

const events = [
  { time: '10:00', title: 'Standup' },
  { time: '14:30', title: 'Design review' }
];
const unreadCount = 4;

return [{ json: { day, events, unreadCount } }];

// Shape the answer for AURA.
//
// `summary` is prose the model reads out or works from. Keep it short:
// it becomes conversation context, and a wall of JSON makes a worse
// spoken answer than a sentence.
//
// Everything else stays structured, so a future tool can use it without
// re-parsing English.

const { day, events, unreadCount } = $input.first().json;

const lines = events.map(e => `${e.time} ${e.title}`).join(', ');
const summary = events.length
  ? `${events.length} events ${day}: ${lines}. ${unreadCount} unread messages.`
  : `Nothing scheduled ${day}. ${unreadCount} unread messages.`;

return [{ json: { summary, day, events, unreadCount } }];
